namespace sharing::mojom {


void NearbySharingDecoderInterceptorForTesting::DecodeAdvertisement(const std::vector<uint8_t>& data, DecodeAdvertisementCallback callback) {
  GetForwardingInterface()->DecodeAdvertisement(std::move(data), std::move(callback));
}
void NearbySharingDecoderInterceptorForTesting::DecodeFrame(const std::vector<uint8_t>& data, DecodeFrameCallback callback) {
  GetForwardingInterface()->DecodeFrame(std::move(data), std::move(callback));
}
NearbySharingDecoderAsyncWaiter::NearbySharingDecoderAsyncWaiter(
    NearbySharingDecoder* proxy) : proxy_(proxy) {}

NearbySharingDecoderAsyncWaiter::~NearbySharingDecoderAsyncWaiter() = default;

void NearbySharingDecoderAsyncWaiter::DecodeAdvertisement(
    const std::vector<uint8_t>& data, ::sharing::mojom::AdvertisementPtr* out_advertisement) {
  base::RunLoop loop;
  proxy_->DecodeAdvertisement(std::move(data),
      base::BindOnce(
          [](base::RunLoop* loop,
             ::sharing::mojom::AdvertisementPtr* out_advertisement
,
             ::sharing::mojom::AdvertisementPtr advertisement) {*out_advertisement = std::move(advertisement);
            loop->Quit();
          },
          &loop,
          out_advertisement));
  loop.Run();
}

::sharing::mojom::AdvertisementPtr NearbySharingDecoderAsyncWaiter::DecodeAdvertisement(
    const std::vector<uint8_t>& data) {
  ::sharing::mojom::AdvertisementPtr async_wait_result;
  DecodeAdvertisement(std::move(data),&async_wait_result);
  return async_wait_result;
}

void NearbySharingDecoderAsyncWaiter::DecodeFrame(
    const std::vector<uint8_t>& data, ::sharing::mojom::FramePtr* out_frame) {
  base::RunLoop loop;
  proxy_->DecodeFrame(std::move(data),
      base::BindOnce(
          [](base::RunLoop* loop,
             ::sharing::mojom::FramePtr* out_frame
,
             ::sharing::mojom::FramePtr frame) {*out_frame = std::move(frame);
            loop->Quit();
          },
          &loop,
          out_frame));
  loop.Run();
}

::sharing::mojom::FramePtr NearbySharingDecoderAsyncWaiter::DecodeFrame(
    const std::vector<uint8_t>& data) {
  ::sharing::mojom::FramePtr async_wait_result;
  DecodeFrame(std::move(data),&async_wait_result);
  return async_wait_result;
}






}  // sharing::mojom


